fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Create a new vector with the same length as input
    // For each character:
    // - If it's an ASCII uppercase letter (between 'A' and 'Z'), convert to lowercase by adding 32
    // - Otherwise, keep the character unchanged
    s.iter()
        .map(|&c| {
            if c >= 'A' && c <= 'Z' {
                // Convert uppercase ASCII letter to lowercase by adding 32 (the difference between 'A' and 'a')
                // This works because ASCII 'A'..'Z' are contiguous and lowercase 'a'..'z' follow immediately.
                ((c as u8) + 32) as char
            } else {
                c
            }
        })
        .collect()
}